@pytest.mark.pre_alloc_mutable
def test_modexp_tests(
    state_test: StateTestFiller,
    pre: Alloc,
    tx_data_hex: str,
    expected_post: dict,
) -> None:
    """Ori Pomerantz qbzzt1@gmail.com."""
    coinbase = Address("0x2adc25665018aa1fe0e6bc666dac8fc2697ff9ba")
    sender = Address("0x485fd0fd5c1d0409d2b772a66e98a6ac867b9d8b")
    contract = Address("0x6082a22dbf403b1af4fe03a0ccbd9bb78defb44a")

    env = Environment(
        fee_recipient=coinbase,
        number=1,
        timestamp=1000,
        prev_randao=0x20000,
        base_fee_per_gas=10,
        gas_limit=100000000,
    )

    pre[sender] = Account(balance=0xba1a9ce0ba1a9ce, nonce=1)
    pre[contract] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=1,
        code=(
        Op.CALLDATALOAD(offset=0x4) + Op.CALLDATALOAD(offset=0x24)
        + Op.CALLDATALOAD(offset=0x44) + Op.SWAP2 + Op.MSTORE(offset=0x0, value=0x20)
        + Op.MSTORE(offset=Op.DUP1, value=0x20) + Op.MSTORE(offset=0x40, value=0x20)
        + Op.PUSH1[0x60] + Op.MSTORE + Op.PUSH1[0x80] + Op.MSTORE + Op.PUSH1[0xa0]
        + Op.MSTORE + Op.PUSH2[0x14c] + Op.GAS
        + Op.POP(Op.CALL(gas=Op.GAS, address=0x5, value=Op.DUP1, args_offset=0x0, args_size=0xc0, ret_offset=0x100, ret_size=0x20))
        + Op.GAS + Op.SWAP1 + Op.SSTORE(key=0x0, value=Op.MLOAD(offset=0x100))
        + Op.SUB + Op.SSTORE(key=0x1, value=Op.SUB) + Op.STOP
    ),
    )

    tx_data = bytes.fromhex(tx_data_hex) if tx_data_hex else b""

    tx = Transaction(
        secret_key=Hash(
            "0x48dc5a9f099caaaa557742ca3a990a94be45b9969126a1bc74e5e8be5a2b5b47"
        ),
        to=contract,
        data=tx_data,
        gas_limit=16777216,
        gas_price=10,
        nonce=1,
        value=0,
    )

    post = expected_post

    state_test(env=env, pre=pre, post=post, tx=tx)
